#!/bin/bash
# gen.sh <topic> <n> <prefix> '<game steps>'  generic theme: station card 开始任务 -> game -> steps -> bag 结算任务 -> 确认装载
n=$2; lat=$(python3 -c "print('%.6f'%(31.2380+$n*0.0003))"); lng=$(python3 -c "print('%.6f'%(121.4900+$n*0.0004))")
timeout 500 node /root/j3t/drive.mjs "{\"identity\":\"e2e-openid-9004\",\"path\":\"pages/play/index?topicId=$1\",\"lat\":$lat,\"lng\":$lng}" "[\"wait:3000\",\"tapx:开始游戏\",\"tapx:继续游戏\",\"wait:9000\",\"tapn:开启定位|1\",\"wait:1500\",\"tapx:继续探索\",\"wait:5000\",\"tapx:继续探索\",\"wait:3000\",\"loc:$lat,$lng\",\"wait:3000\",\"say:pre\",\"shot:$3-a\",\"tapx:开始任务\",\"wait:4000\",\"tapx:确认\",\"tapx:开始\",\"wait:3000\",\"say:game\",\"shot:$3-b\"${4:+,$4},\"wait:2000\",\"click:242,136\",\"wait:2500\",\"tapx:任务\",\"wait:1500\",\"say:bag\",\"shot:$3-c\",\"tapx:结算任务\",\"wait:3000\",\"tapx:确认装载\",\"wait:4000\",\"say:done\",\"shot:$3-d\"]" 2>&1 | grep -E "TEXT|MISS|NET.*/api/play/(advanced|arrive|theme/gameplay)" | grep -v 'MISS tapx:继续游戏\|MISS tapn:开启\|MISS tapx:继续探索' | cut -c1-900
